  // ── Landing "/" (components/screens/Landing.tsx, issue #8) ────────────────────
  "landing.nav.github": "GitHub",
  "landing.nav.login": "Đăng nhập",
  "landing.hero.title": "Agent sửa mô hình của app. Người duyệt và xuất bản.",
  "landing.hero.lead": "Nexus là nền tảng ứng dụng nghiệp vụ dành cho agent. Agent không viết code ứng dụng: nó sửa một mô hình có kiểu, có phiên bản, có phân quyền (bảng, trường, quan hệ, màn hình, quy trình, quyền truy cập). Một engine do người viết chạy mọi app.",
  "landing.hero.demo": "Đăng nhập bản demo",
  "landing.hero.source": "Mã nguồn trên GitHub",
  "landing.hero.imageAlt": "Giao diện thật của Nexus: app CRM với danh sách cơ hội bán hàng",
  "landing.loop.eyebrow": "VÒNG LẶP",
  "landing.loop.title": "Agent đề xuất, người quyết.",
  "landing.loop.propose.title": "Agent đề xuất",
  "landing.loop.propose.body": "Bạn nhờ trợ lý trong Studio, hoặc nhờ Claude Code qua MCP. Agent gọi công cụ đề xuất: công cụ kiểm tra thay đổi rồi giữ lại, không áp gì cả.",
  "landing.loop.publish.title": "Người áp và xuất bản",
  "landing.loop.publish.body": "Mỗi đề xuất là một thẻ có diff, xem trước ngay tại chỗ. Bạn áp thẻ; phần lớn thay đổi chờ ở dạng nháp đến khi bạn xuất bản.",
  "landing.loop.use.title": "Nhân viên dùng app",
  "landing.loop.use.body": "Họ nhận phiên bản đã xuất bản, trong phạm vi quyền của vai mình. Nếu phiên bản mới sai, bạn quay về phiên bản trước.",
  "landing.diff.eyebrow": "KHÁC Ở ĐÂU",
  "landing.diff.title": "Agent sửa một mô hình, không sinh một codebase cho mỗi app.",
  "landing.diff.review.title": "Duyệt một thay đổi, không phải diff code",
  "landing.diff.review.body": "Mỗi đề xuất là diff có kiểu của một tài liệu: một bảng, một trường, một màn hình, một quyền. Bạn xem trước nó ngay tại chỗ.",
  "landing.diff.versions.title": "Nháp, xuất bản, quay lại",
  "landing.diff.versions.body": "Xuất bản là một giao dịch và tạo một phiên bản. Quay lại cũng tạo một phiên bản mới: schema mới hơn bị ẩn lại, không dữ liệu nào bị xoá. Sửa thuộc tính không được hoàn lại; thay đổi áp ngay thì hoàn tác từng mục bằng nút Hoàn tác.",
  "landing.diff.safe.title": "Quyền theo tổ chức và theo dòng, kiểm bằng người không phải admin",
  "landing.diff.safe.body": "Theo quy tắc, mọi truy vấn lọc theo tổ chức (tenant). Quyền theo bảng và theo dòng mặc định từ chối, áp cho cả app lẫn trợ lý của người dùng. Cô lập dựa vào quy ước và test, không phải cơ chế của cơ sở dữ liệu. Nghiệm thu bằng một nhân viên không phải admin, vì admin bỏ qua phân quyền.",
  "landing.diff.mcp.title": "Agent bên ngoài, qua MCP",
  "landing.diff.mcp.body": "Claude Code và Claude Desktop có cùng các công cụ đọc và đề xuất, qua một khoá chỉ dùng được ở /mcp và hết hạn sau tối đa 8 giờ. Đề xuất của chúng thành thẻ trong Studio để bạn áp.",
  "landing.diff.measured.title": "AI có số đo",
  "landing.diff.measured.body": "Hai lượt chạy demo, một tiếng Việt và một tiếng Anh, được ghi lại và phát lại tất định, nên CI chạy vòng demo không cần model, không cần key. builder-bench, đo ngày 17/10/2026: 20 yêu cầu chấm bằng code; pass@1 0,85 với claude-haiku-5-5 (60 lượt) và với claude-opus-5-5 (một lượt mỗi yêu cầu). Eval MCP: 5/5, mỗi yêu cầu chạy một lần với claude-opus-5-5.",
  "landing.diff.run.title": "Chạy bằng một lệnh",
  "landing.diff.run.body": "docker compose up --build dựng MySQL, API, web và dữ liệu demo. Go và MySQL 8, giấy phép MIT.",
  "landing.try.eyebrow": "DÙNG THỬ",
  "landing.try.title": "Chạy bản demo, đọc mã nguồn và bài viết.",
  "landing.try.demo.title": "Bản demo",
  "landing.try.demo.body": "Mã tổ chức northwind. Đăng nhập bằng tài khoản builder để dựng app, hoặc tài khoản nhân viên kinh doanh để thấy đúng những gì vai đó được phép. Tài khoản nằm trong README.",
  "landing.try.source.title": "Mã nguồn và README",
  "landing.try.source.body": "Kiến trúc, các ADR, số đo và giới hạn hiện tại.",
  "landing.try.writeup.title": "Bài viết: Turning the lights back on",
  "landing.try.writeup.body": "Nexus được dựng hai lần: lần đầu bằng nhiều agent chạy song song không ai cầm lái, lần sau từng lát một, có người duyệt. Bài viết bằng tiếng Anh.",
  "landing.footer.note": "Nexus · mã nguồn mở, giấy phép MIT.",

  // ── Page: /about (SLDS cards + accordion) ───────────────────────────────────
  "page.about.guide.title": "Hướng dẫn sử dụng",
  "page.about.guide.meta": "App nghiệp vụ của tổ chức bạn — 1 phút để nắm cách dùng.",
  "page.about.guide.card": "Những điều cần biết",
  "page.about.guide.note": "Thiếu quyền hoặc không thấy dữ liệu bạn cần? Liên hệ quản trị viên của tổ chức bạn — quyền xem/sửa được cấu hình theo vai trò.",
  "page.about.title": "Giới thiệu Nexus",
  "page.about.meta": "5 phút để hiểu engine — dành cho team Nexus và khách được onboard.",
  "page.about.what.title": "Nexus là gì",
  "page.about.what.lead": "Một engine metadata-driven — không phải một phần mềm CRM đóng gói.",
  "page.about.what.body": "Nexus là nền tảng nội bộ của Nexus để dựng phần mềm nghiệp vụ (CRM, LMS, Ticketing, ERP…) cho khách hàng — nhanh, vì 90% là engine dùng chung, chỉ 10% mỗi dự án là tuỳ biến riêng. Nexus không phải SaaS tự đăng ký: khách không tự lắp app, Nexus dùng công cụ Studio để lắp cho khách rồi bàn giao App khách đã hoàn thiện. Toàn bộ: entity/field, quan hệ, layout, phân quyền, workflow, báo cáo… đều là dữ liệu cấu hình (metadata), không phải code viết cứng theo từng entity.",
  "page.about.faces.title": "Hai khuôn mặt",
  "page.about.faces.lead": "Studio để dựng — App khách để vận hành.",
  "page.about.faces.current": "Bạn đang ở đây",
  "page.about.faces.studio.title": "Studio (Builder)",
  "page.about.faces.studio.body": "Xưởng phần mềm nội bộ Nexus — kỹ sư giải pháp dùng Studio để mô hình hoá dữ liệu, nối quan hệ, dựng layout, cấu hình workflow/phê duyệt/báo cáo cho từng khách.",
  "page.about.faces.studio.when": "Dùng khi: bạn là Nexus, đang lắp hoặc chỉnh app cho một khách.",
  "page.about.faces.app.title": "App khách",
  "page.about.faces.app.body": "Ứng dụng nghiệp vụ đã dựng xong bằng Studio — người dùng cuối (khách hoặc chính Nexus khi vận hành demo) làm việc hàng ngày với dữ liệu thật ở đây.",
  "page.about.faces.app.when": "Dùng khi: bạn đang thao tác nghiệp vụ (xem/sửa bản ghi, báo cáo, phê duyệt).",
