  "page.doctor.check.A2A.label": "Cột duy nhất đếm cả bản ghi đã xoá",
  "page.doctor.check.A2A.desc": "Cột kiểm tra trùng của một trường duy nhất vẫn tính bản ghi đã xoá, nên tạo lại bản ghi cùng giá trị bị báo trùng oan. Sửa = đưa cột về đúng dạng chuẩn.",
  "page.doctor.check.A3.label": "Chỉ mục duy nhất còn thừa trên bảng dùng chung",
  "page.doctor.check.A3.desc": "Chỉ mục kiểm tra trùng còn trên bảng dữ liệu nhưng không tổ chức nào còn trường duy nhất dùng nó, thường là dấu vết sau khi xoá trường. Cần tự xử lý: máy không tự gỡ vì tạo lại trường cùng tên sẽ dùng lại cột này. Xác nhận rồi nhờ người phụ trách kỹ thuật gỡ tay.",
  "page.doctor.check.A5.label": "Bảng dữ liệu cũ thiếu cột hoặc chỉ mục bắt buộc",
  "page.doctor.check.A5.desc": "Bảng dữ liệu tạo từ bản phần mềm cũ thiếu cột hệ thống hoặc chỉ mục, nên một số thao tác chậm hoặc lỗi. Sửa = bổ sung phần còn thiếu, không đụng dữ liệu đang có.",
  "page.doctor.check.A6.label": "Bảng dữ liệu của một bảng đã mất",
  "page.doctor.check.A6.desc": "Bảng dữ liệu đang dùng nhưng nơi lưu thật đã bị xoá tay, nên mọi thao tác trên các bản ghi của nó báo lỗi. Sửa = dựng lại nơi lưu RỖNG; dữ liệu cũ không quay lại.",
  "page.doctor.check.B4.label": "Bảng nối nhiều-nhiều bị mất",
  "page.doctor.check.B4.desc": "Hai bảng được nối nhiều-nhiều nhưng nơi lưu các liên kết đã mất, nên thêm hoặc bỏ liên kết đều lỗi. Sửa = dựng lại nơi lưu RỖNG; các liên kết cũ không quay lại.",
  "page.doctor.check.B5.label": "Nơi lưu liên kết không còn quan hệ nào dùng",
  "page.doctor.check.B5.desc": "Còn nơi lưu liên kết nhiều-nhiều nhưng không quan hệ nào đăng ký dùng nó. Cố ý giữ lại một thời gian: đăng ký lại đúng cặp bảng thì liên kết cũ sống lại. Cần tự xử lý: xem tuổi của từng mục rồi quyết định giữ hay dọn.",
  "page.doctor.check.B1.label": "Quan hệ trỏ tới bảng đã xoá",
  "page.doctor.check.B1.desc": "Quan hệ còn trỏ tới một bảng không còn nữa: hiện thừa trên sơ đồ và chiếm mất tên quan hệ. Sửa = gỡ quan hệ thừa khỏi sổ.",
  "page.doctor.check.B2.label": "Quan hệ một-nhiều không còn trường liên kết",
  "page.doctor.check.B2.desc": "Quan hệ một-nhiều còn trong sổ nhưng trường làm khoá liên kết của nó không còn dùng. Sửa = gỡ quan hệ đó khỏi sổ.",
  "page.doctor.check.C1.label": "Màn hình danh sách giữ trường đã xoá",
  "page.doctor.check.C1.desc": "Cách bố trí màn hình đã lưu còn nhắc tới trường đã xoá; hệ thống đang phải tự cắt đi mỗi lần mở. Sửa = lưu lại bản đã bỏ trường thừa.",
  "page.doctor.check.C2.label": "Mục menu của app trỏ tới nơi không còn",
  "page.doctor.check.C2.desc": "Menu của app còn mục dẫn tới bảng hoặc bảng điều khiển đã xoá; hiện bị bỏ qua im lặng. Sửa = xoá mục menu thừa.",
  "page.doctor.check.C4.label": "Luật tự động của một bảng đã xoá vẫn đang bật",
  "page.doctor.check.C4.desc": "Luật tự động còn bật dù bảng của nó đã xoá. Nguy hiểm: tạo lại bảng trùng tên thì luật cũ sống lại âm thầm, tự sửa bản ghi hoặc gửi thông báo. Sửa = tắt luật (không xoá, bật lại được nếu cố ý); cần xác nhận.",
  "page.doctor.check.D1.label": "Sổ kiểm tra trùng lệch với các trường",
  "page.doctor.check.D1.desc": "Sổ dùng để chặn giá trị trùng lệch với các trường duy nhất: thiếu dòng cho trường đang dùng, hoặc còn dòng của trường đã chết. Sửa = đối chiếu hai chiều, bổ sung và dọn, không mất dữ liệu.",
  "page.doctor.check.D2.label": "Bản ghi mang sai mã tiền tệ",
  "page.doctor.check.D2.desc": "Bản ghi cũ lưu trước khi hệ thống chặn lệch mã mang mã tiền tệ khác mã cấu hình của trường, nên tổng và báo cáo cộng sai. Cần tự xử lý: nhập lại số tiền theo đúng mã hoặc sửa dữ liệu gốc; máy không tự đổi nhãn hay quy đổi.",
  "page.doctor.check.D3.label": "Hồ sơ chờ duyệt chưa có người nhận việc",
  "page.doctor.check.D3.desc": "Hồ sơ đang chờ duyệt nhưng chưa ghi ai nhận việc, hoặc ghi lệch (do bản phần mềm cũ). Người duyệt vẫn thấy hồ sơ trong hộp duyệt, không ai mất việc. Cần tự xử lý: không phải làm gì, lần duyệt hoặc uỷ quyền kế tiếp tự ghi lại; số này về 0 ở mọi tổ chức thì gỡ được đường dự phòng.",
  "page.doctor.check.C8.label": "Trường liên kết trỏ tới bảng đã xoá",
  "page.doctor.check.C8.desc": "Trường liên kết trỏ tới một bảng không còn nữa, nên lưu bản ghi có trường này sẽ báo lỗi. Cần tự xử lý: vào Dữ liệu của bảng, xoá trường đó đúng cách, hoặc tạo lại bảng đích.",
  "page.doctor.check.C11.label": "Khoá kết nối còn niêm phong bằng khoá chủ cũ",
  "page.doctor.check.C11.desc": "Sau khi đổi khoá mã hoá chủ, máy chủ tự niêm phong lại từng khoá kết nối bằng khoá mới lúc khởi động. Mục này liệt kê khoá nào chưa được niêm phong lại. Cần tự xử lý: khi số này về 0 ở mọi tổ chức mới được gỡ khoá chủ cũ; gỡ sớm thì các khoá còn lại không mở được.",
  "page.doctor.check.C12.label": "Khoá kết nối không mở được",
  "page.doctor.check.C12.desc": "Khoá kết nối được niêm phong bằng khoá chủ mà máy chủ này không giữ, thường do khôi phục dữ liệu sang môi trường khác. Các quy trình dùng khoá này KHÔNG gửi gì cho đối tác. Cần tự xử lý: đặt lại đúng khoá chủ vào máy chủ, hoặc nhập lại bí mật mới.",
  "page.doctor.check.C10.label": "Khoá trần trong quy trình gửi đối tác cũ",
  "page.doctor.check.C10.desc": "Quy trình lưu trước khi có Kho khoá kết nối còn giữ khoá ký hoặc thông tin xác thực của đối tác dạng chữ thường. Sửa = cất khoá vào Kho khoá kết nối rồi cho quy trình trỏ tới đó; đối tác nhận y nguyên. Đây là bước một chiều: lùi về bản phần mềm trước làm các quy trình đã dời ngừng gửi, và lần gửi đã lỗi của chúng không Gửi lại được nữa (cần thì Gửi lại ở Việc nền trước). Quy trình đã xoá còn khoá trần bị xoá khỏi bản ghi. Khoá nằm ngay trong địa chỉ được giữ nguyên, chỉ liệt kê để chuyển tay. Cần xác nhận.",
  "page.doctor.check.C9.label": "Vai bị khoá trường bắt buộc",
  "page.doctor.check.C9.desc": "Một vai bị ẩn hoặc chỉ-đọc trên trường bắt buộc mà máy không tự điền, nên vai đó không tạo được bản ghi nào. Người dùng chỉ thấy “thiếu một trường bắt buộc không được xem”; tên trường nằm ở đây. Cần tự xử lý: bỏ “bắt buộc”, đặt giá trị mặc định, hoặc gỡ khoá cho vai đó ở phân quyền trường.",

