  "page.sharing.title": "Chia sẻ & Quyền sở hữu",
  "page.sharing.subtitle": "Cách quyền kết hợp từ vai trò và bộ nhóm · màn chỉ đọc",
  "page.sharing.model.title": "Mô hình chia sẻ",
  "page.sharing.model.body": "Mỗi bản ghi thuộc về một chủ sở hữu ({code}) và gắn một bộ nhóm (team set) quyết định ai trong nhóm nào được xem/sửa. Mức truy cập kết hợp từ cả vai trò (ma trận ACL) và bộ nhóm của bản ghi.",
  "page.sharing.order.title": "Thứ tự kiểm tra quyền",
