  "page.sharing.order.4": "Nếu accessLevel = {code}: mọi user trong tenant.",
  "page.sharing.order.5": "Nếu accessLevel = {code}: bản ghi mà trường Người dùng đó trỏ tới user, cộng bản ghi user tạo.",
  "page.sharing.rules.title": "Chia sẻ theo quy tắc — thuộc lộ trình.",
  "page.sharing.rules.body": "Trình tạo quy tắc chia sẻ tổng quát (tự động cấp quyền theo vùng miền, phòng ban, điều kiện bất kỳ…) chưa có. Trường hợp thường gặp đã làm được: ở ma trận vai trò, chọn mức “Hồ sơ có trường … là tôi” để nhân viên thấy hồ sơ giao cho mình (bác sĩ ↔ lịch hẹn, giáo viên ↔ lớp) mà không cần đổi chủ từng hồ sơ.",
  "page.sharing.owner.title": "Chuyển quyền sở hữu bản ghi",
  "page.sharing.owner.body": "Chủ sở hữu mặc định là người tạo bản ghi. Admin, hoặc vai trò có quyền Sửa mức “Tất cả”, bấm “Đổi chủ” trên bản ghi để giao cho người khác (người nhận được báo trong hộp thư). Muốn nhân viên thấy hồ sơ giao cho mình mà không cần đổi chủ từng bản ghi, dùng mức “Hồ sơ có trường … là tôi” trong ma trận vai trò.",
  "page.teamSets.title": "Bộ nhóm (Team Sets)",
  "page.teamSets.intro": "Bộ nhóm được engine tự sinh khi ghi bản ghi (từ các nhóm của người tạo). Mỗi bản ghi gắn một bộ nhóm để quyết định nhóm nào được thấy. Đây là màn chỉ đọc — không tạo/sửa tay.",
